css:
body {
    font-family: Georgia, serif;
    margin: 0;
    padding: 0;
    color: #000;
}

/* Hide elements that shouldn't be printed */
.no-print {
    display: none !important;
}

/* Adjust margins and paddings for print */
@page {
    size: auto;
    margin: 1in;
}

@media print {
    /* Page breaks */
    /*.content {*/
    /*    page-break-after: always;*/
    }
}

body {
    font-family: Arial, sans-serif;
    line-height: 1.6;
}

.content {
    padding: 20px;
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.header {
    display: flex;
    justify-content: center;
    text-transform: uppercase;
    text-align: center;
    margin-bottom: 20px;
}

.details {
    margin-bottom: 20px;
}

.details-row {
    display: flex;
    justify-content: space-between;
    margin-bottom: 10px;
}

.details-row span {
    font-weight: bold;
}

.container-table {
    margin-top: 20px;
}

.container-table table {
    width: 100%;
    border-collapse: collapse;
    font-size: 12px;
}

.container-table th, .container-table td {
    border: 1px solid black;
    padding: 5px;
    text-align: center;
}

.container-table th {
    background-color: #0B5394;
    color: white;
}

.container-table td {
    background-color: #CFE2F3;
}

.notes {
    margin-top: 30px;
}

.notes p {
    font-size: 12px;
    margin-block-end: 5px;
    margin-block-start: 5px;
}

.contact {
    margin-top: 20px;
    font-size: 12px;
}

/* Additional classes for alignment */
.underline {
    text-decoration: underline;
}


h1 {
    font-size: 24pt;
    margin-block-end: 0px;
    margin-block-start: 0px;
}

h5 {
    margin-block-end: 0px;
    margin-block-start: 0px;
    font-size: 15px;
}

.fontSizeP {
    font-size: 10px;
}
